import axios from "axios";
import "./App.css";
import "./ToDoList.css";
import React, { useState, useEffect, useCallback } from "react";
import { FixedSizeList } from "react-window";
import InfiniteLoader from "react-window-infinite-loader";

function ToDoList() {
  const [tasks, setTasks] = useState([]); // Store fetched tasks
  const [searchTerm, setSearchTerm] = useState("");
  const [isLoading, setIsLoading] = useState(false);
  const [hasMore, setHasMore] = useState(true);
  const [page, setPage] = useState(0);

  const pageSize = 50;

  // Load tasks on initial render
  useEffect(() => {
    loadMoreTasks(0);
  }, []);

  // Load more tasks function (pagination logic)
  const loadMoreTasks = useCallback(
    async (currentPage) => {
      if (isLoading || !hasMore) return;

      setIsLoading(true);
      try {
        const response = await axios.get(
          `https://releasetrain.io/api/c/names?start=${
            currentPage * pageSize
          }&limit=${pageSize}`
        );

        if (response.data.length === 0) {
          setHasMore(false); // Stop loading if no more data
        } else {
          // Assuming the API returns an array of names
          setTasks((prevTasks) => [
            ...prevTasks,
            ...response.data.map((item) => ({ text: item, id: item }))
          ]);
          setPage(currentPage + 1);
        }
      } catch (error) {
        console.error("Error loading more tasks:", error);
      }
      setIsLoading(false);
    },
    [isLoading, hasMore, page]
  );

  // Filter tasks based on search term
  const filteredTasks = tasks.filter((task) =>
    task.text.toLowerCase().includes(searchTerm.toLowerCase())
  );

  // Check if the task is already loaded
  const isItemLoaded = (index) => index < filteredTasks.length;

  // Trigger load when reaching the bottom
  const loadMoreItems = async () => {
    if (!isLoading && hasMore) {
      await loadMoreTasks(page);
    }
  };

  // Handle search input change
  const handleSearchChange = (e) => setSearchTerm(e.target.value);

  return (
    <div className="to-do-list">
      <h1>To-Do List</h1>

      {/* Search Bar */}
      <input
        type="text"
        placeholder="Search tasks..."
        value={searchTerm}
        onChange={handleSearchChange}
        className="search-bar"
      />

      {/* Infinite Scrolling */}
      <InfiniteLoader
        isItemLoaded={isItemLoaded}
        itemCount={hasMore ? filteredTasks.length + 1 : filteredTasks.length}
        loadMoreItems={loadMoreItems}
      >
        {({ onItemsRendered, ref }) => (
          <FixedSizeList
            height={600}
            width="100%"
            itemSize={60}
            itemCount={filteredTasks.length}
            onItemsRendered={onItemsRendered}
            ref={ref}
          >
            {({ index, style }) => {
              const task = filteredTasks[index];

              return (
                <div style={style} className="task-item">
                  <span>{task.text}</span>
                </div>
              );
            }}
          </FixedSizeList>
        )}
      </InfiniteLoader>

      {isLoading && <p className="loading-text">Loading more tasks...</p>}
    </div>
  );
}

export default ToDoList;
